# Source of truth for the Transitus requirements register (phase 1, proposed).
# Rendered by tools/render_requirements.py into requirements/requirements.json,
# requirements/REQUIREMENTS.md and requirements/TRACEABILITY.md.
# Fields per requirement: id, category, priority, phase, statement, acceptance, charter, design, decisions, verify
R = []
def req(id, cat, pri, phase, stmt, acc, charter, design, dec=(), verify="test"):
    R.append(dict(id=id, category=cat, priority=pri, phase=phase, statement=stmt,
                  acceptance=acc, charter=charter, design=list(design), decisions=list(dec), verify=verify, status="proposed"))

# --- Pipeline specification (PS)
req("TRN-REQ-PS-001","pipeline-spec","P0",1,"Pipelines MUST be versioned, declarative JSON documents conforming to a published JSON Schema and an F# discriminated-union model; the content hash (SHA-256 of RFC 8785 canonical JSON, excluding annotations) identifies a pipeline version.","Two semantically identical pipelines with different key order or layout annotations produce the same hash; schema-invalid documents are rejected with a located error.","§6",["TRN-ARCH-01 §1, §4","schemas/pipeline.schema.json"],["DF-TRN-2026-0002"])
req("TRN-REQ-PS-002","pipeline-spec","P0",1,"Every stage MUST declare its kind, inputs (dependsOn), outputs, failure behaviour and the provenance it emits, per the lifecycle table.","Publish-time validator rejects a stage lacking required fields; documentation lists inputs/outputs/state/failure/provenance for all 14 stage kinds.","§4",["TRN-ARCH-01 §2"],["DF-TRN-2026-0003"])
req("TRN-REQ-PS-003","pipeline-spec","P0",1,"Pipelines whose destination is classified system-of-record MUST include preserve, blocking validate, blocking reconcile, authorize and evidence stages.","Validator rule PV-12 rejects a system-of-record pipeline missing any of these stages.","§4, §12",["TRN-ARCH-01 §2","TRN-ARCH-06 §4"],["DF-TRN-2026-0011"])
req("TRN-REQ-PS-004","pipeline-spec","P0",1,"Published pipeline versions MUST be immutable; publishing MUST require an authorized role, and pipelines handling restricted-financial or phi classifications MUST require a second approver.","Attempting to modify a published version fails; single-approver publish of a financial pipeline is refused.","§14",["TRN-SEC-01 T11"],["DF-TRN-2026-0002"])
req("TRN-REQ-PS-005","pipeline-spec","P0",1,"Control flow MUST be limited to DAG dependencies, total partitioning routes with a mandatory otherwise branch, union/join merges, runIf predicates over execution facts, per-stage error policies and retries; loops, recursion, user functions and dynamic stage generation MUST NOT be expressible.","JSON Schema and validator reject cycles, missing otherwise branches and any construct outside the list.","§4",["TRN-ARCH-01 §3"],["DF-TRN-2026-0003"])
req("TRN-REQ-PS-006","pipeline-spec","P0",1,"User-configured pipelines MUST NOT contain or evaluate arbitrary executable code, dynamic SQL, JavaScript or unrestricted scripting; extension MUST occur only via reviewed, compiled F# operation packages on a host allow-list.","No schema field accepts code; fuzzed pipeline documents never cause code loading; an unlisted package reference fails validation.","§6",["TRN-ARCH-01 §5","TRN-ARCH-04 §5"],["DF-TRN-2026-0005"])
req("TRN-REQ-PS-007","pipeline-spec","P0",1,"Predicates and computed fields MUST use the typed, total Transitus Expression Language whose evaluation terminates in time linear in expression size.","Type errors are reported at publish; property tests show termination and no exceptions for generated expressions.","§6",["TRN-ARCH-01 §5"],["DF-TRN-2026-0004"])
req("TRN-REQ-PS-008","pipeline-spec","P0",1,"Publish-time validation MUST compute an authority-envelope diff against the prior version and require elevated approval for any widening (new source, destination, egress host, secret slot, classification increase, relaxed gate or tolerance, new loss acknowledgement).","A diff adding an egress host is flagged and cannot publish with standard approval.","§9, §14",["TRN-ARCH-01 §6","TRN-ARCH-07 §4"],["DF-TRN-2026-0012"])
req("TRN-REQ-PS-009","pipeline-spec","P1",1,"Every operation, configuration field, stage kind and error code MUST have AI-readable semantics documentation, generated from or checked against the model.","Documentation-completeness test fails when a DU case lacks semantics text.","§6",["TRN-ARCH-00 P15"],[])
req("TRN-REQ-PS-010","pipeline-spec","P1",1,"The pipeline specification MUST support source, destination and schema definitions, field mappings, type conversion, validation, conditional transformation, lookups, joins, aggregation, filtering, deduplication, normalization, relationship resolution, reference data, reconciliation, error, retry and approval policies, scheduling, resource limits, retention and security classification.","Each listed construct has a schema element and at least one example fixture.","§6",["TRN-ARCH-01 §4","TRN-ARCH-04 §3"],[])
# --- Storage (ST)
req("TRN-REQ-ST-001","storage","P0",2,"Raw inputs MUST be preserved immutably and content-addressed by SHA-256 with tenant, source identifier, source locator, acquisition timestamp, source metadata, adapter version, classification and retention class before any parsing.","Parse stage cannot start without a committed raw object; metadata row contains all listed fields.","§5",["TRN-ARCH-02 §1"],["DF-TRN-2026-0008"])
req("TRN-REQ-ST-002","storage","P0",2,"Source-supplied file names, paths and keys MUST be stored only as metadata and never used to derive storage paths.","Zip-slip and path traversal fixtures produce no file outside the blob store namespace.","§5, §14",["TRN-ARCH-02 §1","TRN-SEC-01 T05"],[])
req("TRN-REQ-ST-003","storage","P0",2,"Staging MUST be typed, tenant-partitioned, chunked and isolated, with DDL produced at publish time through the host's Strata-governed migration path and no runtime ad hoc DDL.","Execution role lacks DDL privilege; staging tables exist only after a governed migration.","§5",["TRN-ARCH-02 §2"],["DF-TRN-2026-0008"])
req("TRN-REQ-ST-004","storage","P0",2,"Processing MUST NOT require the full dataset to fit in memory; memory use MUST be bounded by the pipeline memory budget independent of record count.","A 10x larger input does not increase peak working set beyond the configured budget (measured).","§5",["TRN-ARCH-12 §2"],[])
req("TRN-REQ-ST-005","storage","P1",2,"Transformed datasets MUST be sealed by a Merkle root over chunk hashes, and approval and load MUST bind to that root.","Mutating a staged row after approval causes load to refuse with HASH_MISMATCH.","§5",["TRN-ARCH-02 §3"],[])
req("TRN-REQ-ST-006","storage","P0",2,"Staging MUST have an enforced TTL, MUST NOT be exposed through general query APIs, and MUST NOT be used as a source by any other tenant or application.","Sweeper purges expired partitions and records purge evidence; no API returns staged rows except bounded, classification-masked previews.","§5",["TRN-ARCH-02 §6"],[])
req("TRN-REQ-ST-007","storage","P1",2,"The blob store MUST be a port with a PostgreSQL-backed default and an optional S3-compatible implementation.","Conformance tests pass for both implementations.","§5, §16",["TRN-ARCH-02 §1"],["DF-TRN-2026-0008"])
req("TRN-REQ-ST-008","storage","P2",4,"File-backed columnar staging MAY be introduced for executions above ~10^7 records only after measured evidence shows database staging is inadequate, without adding a deployment component.","Decision record cites measurements.","§5, §18",["TRN-ARCH-12 §3"],["DF-TRN-2026-0008"],"review")
# --- Transformation (TX)
req("TRN-REQ-TX-001","transformation","P0",1,"Every transformation operation MUST be versioned (name@major) and pinned by pipelines; behavioural change requires a new major version.","Changing golden output of an operation without a major bump fails CI.","§7",["TRN-ARCH-04 §1"],["DF-TRN-2026-0004"])
req("TRN-REQ-TX-002","transformation","P0",1,"Transformations MUST be pure and total: they return Ok or a typed error, never throw for data-dependent reasons and never perform I/O.","Property tests with arbitrary inputs observe no exceptions; operations have no I/O dependencies.","§7",["TRN-ARCH-04 §1"],["DF-TRN-2026-0004"])
req("TRN-REQ-TX-003","transformation","P0",1,"Culture, locale, time zone (with pinned tzdb version), Unicode normalization form and rounding mode MUST be explicit parameters; host ambient settings MUST NOT influence results.","Tests run under different host cultures and TZ produce identical outputs.","§7",["TRN-ARCH-04 §4"],[])
req("TRN-REQ-TX-004","transformation","P0",1,"Operations that may lose information MUST be rejected unless the stage carries an acknowledgeLoss with reason; reversible, reversible-with-key and irreversible operations MUST be classified.","Validator rejects truncate/round/mask without acknowledgement; descriptor lists reversibility for every operation.","§7",["TRN-ARCH-04 §1, §3"],[])
req("TRN-REQ-TX-005","transformation","P0",1,"Financial values MUST use decimal types only and MUST NEVER be silently truncated, rounded, discarded or reinterpreted; scale reduction requires an explicit rounding operation with declared mode and approval reference.","Parsing 1.005 into a 2-scale money field returns PRECISION_LOSS; floats are rejected for Money fields.","§7, §12",["TRN-ARCH-04 §3.2"],[])
req("TRN-REQ-TX-006","transformation","P0",1,"Missing, explicit-null and present values MUST be distinguished, and every operation MUST declare its behaviour for each.","Coalescing occurs only via explicit operations; tests cover all three cases per operation.","§7",["TRN-ARCH-04 §1"],[])
req("TRN-REQ-TX-007","transformation","P0",1,"Lookups MUST reference versioned reference sets whose versions are recorded in the execution manifest.","Replaying with the same manifest yields identical lookup results after reference data has changed.","§7, §9",["TRN-ARCH-04 §1"],[])
req("TRN-REQ-TX-008","transformation","P0",2,"Record matching MUST produce scored candidates; financial entities MUST NOT be auto-merged, and candidates between configured thresholds MUST go to review.","Matching fixtures show no automatic merges for financial entity types.","§7",["TRN-ARCH-04 §3.6"],[])
req("TRN-REQ-TX-009","transformation","P1",1,"The standard library MUST provide the operation catalogue in TRN-ARCH-04 §3 (string, Unicode, whitespace, date/time/zone, decimal, currency, enum, identifier, address, null, default, split, concat, conditional, math, lookup, matching, duplicate detection, relationship resolution, aggregation, masking, redaction, hashing, tokenization).","Catalogue coverage test enumerates all listed operations.","§7",["TRN-ARCH-04 §3"],[])
req("TRN-REQ-TX-010","transformation","P0",1,"Hashing of low-entropy identifiers MUST use keyed HMAC with a tenant-scoped key; unkeyed hashing of such identifiers MUST be rejected.","Validator rejects privacy.hash with sha256 on fields typed ssn/ein/phone.","§7, §14",["TRN-ARCH-04 §3.7"],[])
# --- Adapters (AD)
req("TRN-REQ-AD-001","adapters","P0",1,"Adapters MUST be separated into transport, format and destination roles behind published F# contracts, independently packaged, with the core depending only on the abstractions.","A new format adapter is added and passes conformance without changes to Transitus.Engine.","§8",["TRN-ARCH-03 §1, §5"],["DF-TRN-2026-0009"])
req("TRN-REQ-AD-002","adapters","P0",1,"Every adapter MUST declare capabilities, configuration schema, secret slots, egress derivation and an error taxonomy mapped to Transient, RateLimited, AuthFailure, PermanentInput, PermanentConfig or Ambiguous.","Descriptor validates against schemas/adapter-descriptor.schema.json; unknown write errors classify as Ambiguous.","§8",["TRN-ARCH-03 §1, §2","schemas/adapter-descriptor.schema.json"],[])
req("TRN-REQ-AD-003","adapters","P0",1,"Adapters MUST support connection testing without mutation and MUST ship synthetic fixtures for conformance testing.","Conformance suite runs every adapter's Test and fixtures offline.","§8",["TRN-ARCH-03 §3"],[])
req("TRN-REQ-AD-004","adapters","P0",2,"Incremental transports MUST persist opaque, versioned checkpoints that advance only after downstream stage commit.","Crash after acquisition but before stage commit re-acquires the same items.","§8, §11",["TRN-ARCH-03 §3","TRN-ARCH-05 §4"],[])
req("TRN-REQ-AD-005","adapters","P0",1,"Phase-1 adapters MUST cover upload, HTTPS, CSV/TSV, fixed-width, XLSX, JSON/NDJSON, staging-only sink and the Unbound domain API destination; further adapters MUST be justified by a consumer scenario.","Adapter catalogue lists the driving scenario for each adapter.","§8",["TRN-ARCH-03 §4"],["DF-TRN-2026-0009"],"review")
req("TRN-REQ-AD-006","adapters","P0",1,"Adapters MUST honour rate limits and Retry-After, and MUST NOT implement internal retry loops; retries are engine-owned.","Adapter conformance asserts single attempt per call.","§8",["TRN-ARCH-03 §3"],[])
req("TRN-REQ-AD-007","adapters","P0",2,"Destination adapters MUST declare a delivery guarantee (idempotent-key, natural-upsert, query-before-write, none) and support read-back where the destination allows.","Engine selects retry/verification policy from the declared guarantee.","§8, §11",["TRN-ARCH-05 §6"],["DF-TRN-2026-0007"])
req("TRN-REQ-AD-008","adapters","P0",1,"Loads into regulated Unbound workflows MUST occur through Unbound domain APIs or approved domain interfaces; Transitus MUST NOT hold credentials to write business tables directly.","Unbound destination adapter uses only published domain operations; no database credentials for Unbound business schemas exist in Transitus configuration.","§5, §14",["TRN-ARCH-02 §4","TRN-ARCH-00 P6"],[])
req("TRN-REQ-AD-009","adapters","P1",2,"Snapshot-diff by natural key MUST be supported for full-file feeds.","BMF fixture yields correct adds, changes and removals versus the prior snapshot.","§8",["TRN-ARCH-03 §6"],[])
req("TRN-REQ-AD-010","adapters","P2",2,"Bidirectional synchronization and conflict resolution MUST NOT be built; outbound flows are separate one-directional pipelines.","Scope review.","§8",["TRN-ARCH-03 §6"],[],"review")
# --- Execution (EX)
req("TRN-REQ-EX-001","execution","P0",2,"Durable execution (queueing, leases, retries, idempotent intake, ordering, approval waits, quarantine, OutcomeUnknown, per-tenant fairness, pause) MUST be provided by Echelon.Execution; Transitus MUST NOT implement a separate queue.","Transitus.Engine has no queue tables; stage commands appear in Echelon.Execution history.","§11, §16",["TRN-ARCH-05 §2"],["DF-TRN-2026-0006"],"review")
req("TRN-REQ-EX-002","execution","P0",2,"The engine MUST implement an explicit pipeline execution state machine including Blocked, PartiallyLoaded and OutcomeUnknown states whose legal transitions are defined by a total pure function.","Exhaustive transition tests; illegal transitions return errors.","§11",["TRN-ARCH-05 §3"],["DF-TRN-2026-0007"])
req("TRN-REQ-EX-003","execution","P0",2,"Batch, incremental, scheduled, manual, event-triggered, dry-run and replay modes MUST be supported.","Each mode has an acceptance test.","§11",["TRN-ARCH-05 §4"],[])
req("TRN-REQ-EX-004","execution","P0",2,"Dry runs MUST execute stages 1-9 and produce a load plan without writing to any system of record.","Dry run against the Unbound adapter performs zero domain commands.","§11",["TRN-ARCH-05 §4"],[])
req("TRN-REQ-EX-005","execution","P0",2,"Processing MUST be chunked with per-chunk checkpoints enabling resumption, cancellation and parallelism where declared.","Kill a worker mid-run; resumed run produces identical outputs with no duplicate chunks.","§11",["TRN-ARCH-05 §5"],[])
req("TRN-REQ-EX-006","execution","P0",2,"Each destination record MUST carry a deterministic idempotency key derived from tenant, pipeline, destination, declared natural key and business date.","Replay produces identical keys; destination dedupes.","§11, §14",["TRN-ARCH-05 §6"],["DF-TRN-2026-0007"])
req("TRN-REQ-EX-007","execution","P0",2,"Transitus MUST NOT claim exactly-once delivery; ambiguous external effects MUST enter OutcomeUnknown and be resolved by verification or reconciliation, never by blind retry.","Simulated timeout after send yields OutcomeUnknown and no retry.","§11",["TRN-ARCH-05 §6"],["DF-TRN-2026-0007"])
req("TRN-REQ-EX-008","execution","P0",2,"Load intent MUST be committed before the external call and the receipt after it; no transaction spans the network.","Crash-injection test at each point leaves a resolvable state.","§11",["TRN-ARCH-05 §7"],[])
req("TRN-REQ-EX-009","execution","P0",2,"Compensation of loaded financial records MUST NOT be automatic.","No code path issues reversal commands.","§11, §12",["TRN-ARCH-05 §8"],[],"review")
req("TRN-REQ-EX-010","execution","P0",2,"Resource limits (input bytes, record bytes, records, nesting depth, archive entries and ratio, memory budget, parallelism, CPU time) and backpressure MUST be enforced.","Limit fixtures fail fast with typed errors; queue depth stays bounded under slow destinations.","§11, §14",["TRN-ARCH-05 §5","TRN-SEC-01 T07"],[])
req("TRN-REQ-EX-011","execution","P1",2,"Cancellation MUST be cooperative and MUST NOT leave unrecorded external effects.","Cancel during load; all in-flight receipts recorded.","§11",["TRN-ARCH-05 §9"],[])
req("TRN-REQ-EX-012","execution","P1",2,"Schedules MUST declare an IANA time zone and misfire policy and be materialized as ScheduledCommands, without a separate scheduler service.","DST transition fixtures schedule correctly.","§11",["TRN-ARCH-05 §4"],[])
# --- Validation & reconciliation (VR)
req("TRN-REQ-VR-001","validation-reconciliation","P0",2,"Transitus MUST provide generic validation primitives for required, type, range, pattern, code set, check digit, cross-field, uniqueness, referential integrity, completeness, sequence, freshness and distribution.","Primitive catalogue tests.","§12",["TRN-ARCH-06 §2"],["DF-TRN-2026-0011"])
req("TRN-REQ-VR-002","validation-reconciliation","P0",2,"Transitus MUST provide reconciliation primitives for counts, control totals, hash totals, balance (opening + movements = closing), keyed set matching, cross-file, cross-system and timing differences.","Primitive catalogue tests including NACHA control and hash totals.","§12",["TRN-ARCH-06 §3"],["DF-TRN-2026-0011"])
req("TRN-REQ-VR-003","validation-reconciliation","P0",2,"Monetary reconciliation tolerance MUST default to zero; non-zero tolerances MUST be declared with justification and appear in evidence.","Profile without tolerance treats a one-cent difference as Unbalanced.","§12",["TRN-ARCH-06 §3"],[])
req("TRN-REQ-VR-004","validation-reconciliation","P0",2,"Blocking validation and reconciliation gates MUST prevent all downstream stages, including load, when they fail.","Failing gate leaves execution Blocked with zero destination effects.","§12",["TRN-ARCH-06 §4"],[])
req("TRN-REQ-VR-005","validation-reconciliation","P0",2,"Gate overrides MUST be elevated authorizations with justification, recorded in evidence, and MUST NOT modify data.","Override evidence present; staged data hash unchanged.","§12",["TRN-ARCH-06 §4"],[])
req("TRN-REQ-VR-006","validation-reconciliation","P0",2,"Unbound-specific accounting rules MUST live in Unbound-owned profiles, not in Transitus core.","No Unbound domain terms in Transitus core packages (dependency/term scan).","§12, §21",["TRN-ARCH-06 §1"],["DF-TRN-2026-0011"],"review")
req("TRN-REQ-VR-007","validation-reconciliation","P0",2,"Every stage MUST satisfy the conservation law in = out + rejected + quarantined + deduplicated + filteredWithCount; discards without counts MUST be impossible.","Engine assertion; mutation test that drops a record fails the execution.","§12",["TRN-ARCH-06 §5"],[])
req("TRN-REQ-VR-008","validation-reconciliation","P0",2,"Record-level exceptions MUST be typed, grouped by code and resolvable only by mapping change, reference data, corrected source or approved exclusion; staged values MUST NOT be hand-edited.","No API mutates staged values.","§12",["TRN-ARCH-06 §6"],[])
req("TRN-REQ-VR-009","validation-reconciliation","P0",2,"Transitus MUST NOT introduce balancing entries, write-offs, suspense entries or silently discarded records.","Review and tests: no operation emits synthetic financial records.","§12",["TRN-ARCH-06 §1"],[],"review")
req("TRN-REQ-VR-010","validation-reconciliation","P0",2,"Post-load verification MUST reconcile planned, loaded and read-back counts and totals.","Verify stage report present in evidence for every system-of-record load.","§11, §12",["TRN-ARCH-05 §6","TRN-ARCH-06 §3"],[])
req("TRN-REQ-VR-011","validation-reconciliation","P1",2,"Duplicate detection MUST operate within file, execution and destination (via read-back) scopes.","Fixtures for each scope.","§12",["TRN-ARCH-06 §2"],[])
req("TRN-REQ-VR-012","validation-reconciliation","P1",2,"Timing differences MUST be classified separately from breaks using declared windows.","Settlement fixture classifies T+1 items as timing.","§12",["TRN-ARCH-06 §3"],[])
# --- AI (AI)
req("TRN-REQ-AI-001","ai","P1",3,"AI assistance MUST produce proposals only as PipelineDiff documents with rationale and confidence; it MUST NOT execute, publish, approve or load.","Assistant tool surface is read-only plus propose.","§9",["TRN-ARCH-07 §1, §4"],["DF-TRN-2026-0012"])
req("TRN-REQ-AI-002","ai","P0",3,"AI-generated configuration MUST pass the same deterministic validation, dry run and authorization gates as human changes.","Proposal acceptance path identical; tests.","§9",["TRN-ARCH-07 §1"],["DF-TRN-2026-0012"])
req("TRN-REQ-AI-003","ai","P0",3,"Source data, documents and external metadata MUST be treated as untrusted, passed as delimited data with provenance tags.","Prompt construction tests.","§9",["TRN-ARCH-07 §4"],[])
req("TRN-REQ-AI-004","ai","P0",3,"Prompt injection MUST NOT be able to change pipeline authority or execution behaviour; an adversarial corpus MUST run in CI.","No authority-widening diff accepted across the corpus.","§9, §14",["TRN-ARCH-07 §4","TRN-SEC-01 T09"],[])
req("TRN-REQ-AI-005","ai","P0",1,"Identical raw inputs, pipeline version, package versions, reference data versions, execution parameters and engine version MUST produce equivalent deterministic results; the runtime path MUST contain no model calls.","Replay determinism test; dependency scan of Engine finds no AI provider.","§9",["TRN-ARCH-01 §7","TRN-ARCH-07 §3"],["DF-TRN-2026-0012"])
req("TRN-REQ-AI-006","ai","P1",3,"AI proposals MUST record model, provider, prompt template version and input/output hashes in pipeline provenance.","Provenance present on accepted proposals.","§9",["TRN-ARCH-07 §3"],[])
req("TRN-REQ-AI-007","ai","P0",3,"By default AI MUST receive schema metadata and synthetic or masked samples only; real samples require tenant policy permission and an approved provider for the data classification.","Classification-gated prompt builder tests.","§9, §14",["TRN-ARCH-07 §4","TRN-SEC-01 T23"],[])
req("TRN-REQ-AI-008","ai","P2",3,"AI mapping accuracy MUST be measured against ground-truth packages before any accuracy claim is made.","Evaluation harness report.","§9, §19",["TRN-ARCH-07 §5"],[],"review")
# --- Mapping packages (MP)
req("TRN-REQ-MP-001","mapping-packages","P0",1,"Mapping packages MUST be versioned, content-hashed, configuration-only bundles that contain no customer data and no code.","Package lint rejects code files and non-synthetic fixtures.","§10",["TRN-ARCH-09 §1","schemas/mapping-package.schema.json"],["DF-TRN-2026-0014"])
req("TRN-REQ-MP-002","mapping-packages","P0",1,"Each package MUST declare the basis of its format knowledge (public specification, public API documentation, customer-authorized sample, synthetic representation); proprietary vendor schemas MUST NOT be invented.","Manifest basis required by schema; review checklist.","§10",["TRN-ARCH-09 §2"],["DF-TRN-2026-0014"],"review")
req("TRN-REQ-MP-003","mapping-packages","P0",1,"Customer-specific configuration MUST be expressed as overlays restricted to package-declared paths, not as forks.","Overlay touching undeclared path is rejected.","§10",["TRN-ARCH-09 §1"],[])
req("TRN-REQ-MP-004","mapping-packages","P1",3,"Packages MUST declare accepted source format versions with detectors and provide a dry-run upgrade diff against fixtures and recent raw inputs.","Upgrade command produces deterministic output diff.","§10",["TRN-ARCH-09 §4"],[])
req("TRN-REQ-MP-005","mapping-packages","P1",3,"Promotion of improvements from customer overlays to base packages MUST carry no customer values and require disclosure review.","Promotion checklist and synthetic fixture regeneration.","§10",["TRN-ARCH-09 §5"],[],"review")
# --- Lineage & evidence (LN)
req("TRN-REQ-LN-001","lineage-evidence","P0",2,"Every material destination record MUST be traceable to original source, source record identifier, source version, pipeline version, mapping version, operations, reference data versions, validation results, authorization decision, execution identifier and destination response.","Lineage query returns all elements for a loaded record.","§13",["TRN-ARCH-08 §2"],["DF-TRN-2026-0013"])
req("TRN-REQ-LN-002","lineage-evidence","P0",2,"Field-level lineage MUST be provided statically per pipeline version; per-record field values MUST NOT be stored except for fields marked lineageCaptureValue (selection codes only).","Static graph present; storage test shows no per-field value table.","§13",["TRN-ARCH-08 §1"],["DF-TRN-2026-0013"])
req("TRN-REQ-LN-003","lineage-evidence","P0",2,"Every execution MUST produce an evidence package (manifest, conservation table, validation, reconciliation, approvals, receipts summary, exceptions summary, hash chain).","Evidence stage output validated against schema.","§13",["TRN-ARCH-08 §3"],[])
req("TRN-REQ-LN-004","lineage-evidence","P1",4,"Evidence reports MUST be renderable through Folio.","Folio template renders a fixture package.","§13",["TRN-ARCH-08 §3"],[])
req("TRN-REQ-LN-005","lineage-evidence","P0",2,"Approvals MUST be recorded as signed events with identity, timestamp, plan hash and validation snapshot hash.","Approval events verify.","§13, §14",["TRN-SEC-01 T20"],[])
req("TRN-REQ-LN-006","lineage-evidence","P0",2,"Evidence MUST be hash-chained per execution and anchored in an append-only per-tenant chain.","Tampering fixture detected.","§13, §14",["TRN-ARCH-08 §3"],[])
req("TRN-REQ-LN-007","lineage-evidence","P1",2,"Operational telemetry MUST be emitted via OpenTelemetry through the host; unresolved exceptions and OutcomeUnknown obligations MAY raise Vigila follow-ups when present.","Absent-safe integration test with and without Vigila.","§13",["TRN-ARCH-08 §3","TRN-ARCH-11 §1"],["DF-TRN-2026-0015"])
req("TRN-REQ-LN-008","lineage-evidence","P0",2,"Logs, telemetry and evidence MUST NOT contain values of fields classified above internal.","Log-leak test suite.","§13, §14",["TRN-ARCH-08 §4"],[])
req("TRN-REQ-LN-009","lineage-evidence","P2",4,"OpenLineage RunEvent export MAY be provided as an optional adapter.","Export validates against OpenLineage spec.","§13",["TRN-ARCH-08 §3"],[])
# --- Security (SEC)
for i,(t,a,ref) in enumerate([
 ("Parsers MUST be pure over byte streams with no ambient authority, pinned versions and continuous fuzzing.","Fuzz corpus runs in CI.","T01"),
 ("Archive handling MUST enforce compressed size, uncompressed size, entry count, nesting depth and compression-ratio limits while streaming.","Zip-bomb fixtures rejected before allocation.","T02"),
 ("XML parsing MUST prohibit DTDs and external resolution and bound document size.","XXE and billion-laughs fixtures rejected.","T03"),
 ("Transitus-generated CSV/XLSX MUST neutralize formula-leading cells; imported formulas MUST NOT be evaluated.","Formula-injection fixtures.","T04"),
 ("Path traversal from archive entries or source names MUST be impossible.","Zip-slip fixtures.","T05"),
 ("Malformed input MUST produce typed, located errors with no silent repair.","Malformed corpus.","T06"),
 ("Resource exhaustion MUST be bounded by per-pipeline limits and non-backtracking regex with timeouts.","Limit fixtures.","T07"),
 ("Data poisoning MUST be mitigated through independent control totals, reference validation, anomaly thresholds and approval gates.","Poisoning fixtures blocked by gates.","T08"),
 ("Secrets MUST be referenced by name only, resolved from the host secret provider and never persisted in pipelines, staging, lineage, logs or prompts.","Secret-leak scan.","T10"),
 ("Pipeline changes MUST be authorized, versioned and separated by duty for sensitive classifications.","Publish authorization tests.","T11"),
 ("Tenant isolation MUST apply to raw, staging, lineage, exceptions and evidence; cross-tenant references MUST be inexpressible.","Cross-tenant fixture rejected.","T12"),
 ("Staging MUST be encrypted at rest per host policy and purged per TTL with evidence.","Purge evidence.","T13"),
 ("Destinations MUST be registered by the host and granted per tenant; pipelines cannot introduce destinations.","Unregistered destination rejected.","T15"),
 ("Third-party parser libraries MUST be isolated and limited and tracked for vulnerabilities.","Dependency scan.","T01"),
 ("Network egress MUST be restricted to per-adapter-instance allow-lists with redirect checks.","Egress test.","T16"),
 ("Replays MUST be explicit and produce the original idempotency keys; duplicate raw inputs MUST be detected.","Replay fixture zero effects.","T17"),
 ("Dependencies MUST be pinned with lock files, SBOM and vulnerability scanning.","CI evidence.","T19"),
 ("Retention MUST be enforced, with crypto-shredding where physical erasure cannot be guaranteed.","Retention tests.","§4.10"),
],1):
    req(f"TRN-REQ-SEC-{i:03d}","security","P0",2,t,a,"§14",[f"TRN-SEC-01 {ref}"],[])
